import{_ as e,o,c as a,a2 as r}from"./chunks/framework.vLhlLNVn.js";const n="/assets/assistent-datenpunkt.C6UwfmmC.png",y=JSON.parse('{"title":"My first meter in 10 minutes","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/01.erste-schritte/02.erster-zaehler.md"},"headers":[],"relativePath":"adapter/sourceanalytix/erste-schritte/erster-zaehler.md","filePath":"adapter/sourceanalytix/erste-schritte/erster-zaehler.md","lastUpdated":null}'),i={name:"adapter/sourceanalytix/erste-schritte/erster-zaehler.md"};function s(d,t,u,h,l,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="my-first-meter-in-10-minutes" tabindex="-1">My first meter in 10 minutes <a class="header-anchor" href="#my-first-meter-in-10-minutes" aria-label="Permalink to &quot;My first meter in 10 minutes&quot;">​</a></h1><p><a id="start-values-unit"></a></p><h2 id="what-do-i-enter-for-the-start-values-and-in-which-unit" tabindex="-1">What do I enter for the start values (and in which unit)? <a class="header-anchor" href="#what-do-i-enter-for-the-start-values-and-in-which-unit" aria-label="Permalink to &quot;What do I enter for the start values (and in which unit)?&quot;">​</a></h2><p>Usually nothing. If you leave the fields empty, every period counts from activation, and SourceAnalytix then sets the start values itself at each period rollover. If you do enter something, it is a meter reading, not a consumption: the reading at the start of the period, in the unit of the price definition.</p><p>A period&#39;s consumption is the total minus its start value. So each field takes the reading at this point in time (system time of the ioBroker host):</p><table tabindex="0"><thead><tr><th>Field</th><th>Reading on</th></tr></thead><tbody><tr><td>&quot;Day&quot;</td><td>today, 0:00</td></tr><tr><td>&quot;Week&quot;</td><td>Monday of this week, 0:00</td></tr><tr><td>&quot;Month&quot;</td><td>the 1st of this month, 0:00</td></tr><tr><td>&quot;Quarter&quot;</td><td>1 January, April, July or October, 0:00</td></tr><tr><td>&quot;Year&quot;</td><td>1 January, 0:00</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>The unit is that of the price definition, not that of the datapoint. If your meter reports 12,345,678 Wh and the price uses kWh, &quot;Day&quot; takes <code>12340</code>, for example, not <code>12340000</code>. The wizard and the detail view show the unit next to every field.</p></div><h3 id="when-to-enter-something-yourself" tabindex="-1">When to enter something yourself <a class="header-anchor" href="#when-to-enter-something-yourself" aria-label="Permalink to &quot;When to enter something yourself&quot;">​</a></h3><p>Only if consumption before activation should count too, for example the whole month although you set up on the 15th. For that you need the real readings from back then, say from a photo of the meter.</p><ol><li>In the wizard&#39;s &quot;Start values&quot; step, choose the &quot;Include consumption since the start of the period&quot; card.</li><li>Enter the readings without a thousands separator (<code>12475.5</code>). A single comma or a single dot is always the decimal mark. If you don&#39;t know a reading, leave the field empty.</li><li>Each field shows &quot;Consumption since start: …&quot; or an error underneath. As long as a field shows an error, &quot;Next&quot; stays locked.</li><li>Finish with &quot;⚡ Activate&quot;.</li></ol><p>Example: you activate on Wednesday, 15 March, and the total is 12,480 kWh.</p><table tabindex="0"><thead><tr><th>Field</th><th>Entry</th><th>Consumption</th></tr></thead><tbody><tr><td>&quot;Day&quot;</td><td><code>12475</code></td><td>5 kWh</td></tr><tr><td>&quot;Week&quot;</td><td><code>12440</code></td><td>40 kWh</td></tr><tr><td>&quot;Month&quot;</td><td><code>12300</code></td><td>180 kWh</td></tr><tr><td>&quot;Quarter&quot;</td><td><code>11900</code></td><td>580 kWh</td></tr><tr><td>&quot;Year&quot;</td><td><code>11900</code></td><td>580 kWh</td></tr></tbody></table><p>No start value may be greater than the total. &quot;Day&quot; is the largest, &quot;Month&quot; is at least as large as &quot;Quarter&quot;, and &quot;Quarter&quot; at least as large as &quot;Year&quot;. &quot;Week&quot; depends on when it started. If a value only fits after dividing by 1000, the page asks something like &quot;Looks like Wh – did you mean 1.29 kWh?&quot;.</p><p>For a running source, change the start values in its detail view under &quot;Start values&quot; and confirm with &quot;⚡ Apply&quot;. An emptied field counts from that moment. Start values only apply until the next period rollover, so earlier periods cannot be filled in this way. For a power source (W), leave the fields empty.</p><p><strong>See also:</strong> <a href="./../anleitungen/zaehlerstaende-korrigieren#values-negative-after-entering-start">Why are my values negative after I entered start values?</a> · <a href="./../hintergrund/perioden-und-zeit#sourceanalytix-calculate-retroactively-only-activation">Does SourceAnalytix calculate retroactively?</a></p><p><a id="datapoint-enable-meter-kwh-power"></a></p><h2 id="which-datapoint-do-i-activate-meter-kwh-or-power-w" tabindex="-1">Which datapoint do I activate: meter (kWh) or power (W)? <a class="header-anchor" href="#which-datapoint-do-i-activate-meter-kwh-or-power-w" aria-label="Permalink to &quot;Which datapoint do I activate: meter (kWh) or power (W)?&quot;">​</a></h2><p>Use your device&#39;s total counter, the value in kWh, Wh or m³ that only goes up, for example <code>ENERGY_Total</code> on Tasmota or <code>GAS_ENERGY</code> instead of <code>GAS_POWER</code>. Only use a power value in W if there is no meter reading.</p><table tabindex="0"><thead><tr><th></th><th>Meter reading (kWh, m³ …)</th><th>Power (W, kW …)</th></tr></thead><tbody><tr><td>Calculation</td><td>total minus start value</td><td>power times time until the next value</td></tr><tr><td>Accuracy</td><td>as accurate as the meter</td><td>an estimate, better the more often the device sends</td></tr><tr><td>SourceAnalytix was stopped</td><td>nothing is missing</td><td>the energy during the pause is missing</td></tr><tr><td>Device restarts at 0</td><td>detected as a reset</td><td>does not matter</td></tr></tbody></table><p>Daily values such as <code>ENERGY_Today</code> or &quot;yield today&quot; are not suitable. The wizard marks them as &quot;daily counter&quot;. They do work, but whatever the device counts around midnight is lost.</p><h3 id="if-you-only-have-a-power-value" tabindex="-1">If you only have a power value <a class="header-anchor" href="#if-you-only-have-a-power-value" aria-label="Permalink to &quot;If you only have a power value&quot;">​</a></h3><p>In the wizard, choose the type &quot;Power&quot; and a price definition with an energy unit, for example kWh. The first value is only the starting point; consumption starts with the second. The detail view has three options for this under &quot;Settings&quot;:</p><ul><li>&quot;Average power values&quot;: calculates with the average of two values. Suits sensors that send regularly.</li><li>&quot;Ignore negative values&quot;: for inverters that report negative power in standby.</li><li>&quot;Maximum gap between power values (minutes)&quot;: if no value arrives for longer, the gap counts as 0. Leave the field empty for devices that only send on change.</li></ul><p><strong>See also:</strong> <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">How does SourceAnalytix convert watts to kWh?</a> · <a href="./../hintergrund/zaehler-reset#counter-reset-0-daily-happens">Counter that is reset to 0 every day</a></p><p><a id="configure-sourceanalytix-datapoint"></a></p><h2 id="where-do-i-configure-sourceanalytix-for-a-datapoint" tabindex="-1">Where do I configure SourceAnalytix for a datapoint? <a class="header-anchor" href="#where-do-i-configure-sourceanalytix-for-a-datapoint" aria-label="Permalink to &quot;Where do I configure SourceAnalytix for a datapoint?&quot;">​</a></h2><p>In the SourceAnalytix instance settings. On the &quot;Overview&quot; tab, &quot;Add source&quot; starts a wizard that activates the source right away, without a restart. You need a running instance and at least one price definition first.</p><ol><li><strong>&quot;Datapoint&quot;:</strong> search for the meter reading or pick it with &quot;Select object&quot;.</li><li><strong>&quot;Type&quot;:</strong> &quot;Meter reading&quot; or &quot;Power&quot;. For a meter reading, the wizard asks whether the value sometimes drops to 0. &quot;Yes&quot; turns reset detection on.</li><li><strong>&quot;Unit&quot;:</strong> check the detected unit.</li><li><strong>&quot;Price&quot;:</strong> choose the price definition. Unsuitable units are marked &quot;other unit&quot;. For a pulse counter (unit pcs), enter the pulses per unit here, for example 1000 for 1000 imp/kWh.</li><li><strong>&quot;Calculation&quot;:</strong> &quot;Consumption&quot;, &quot;Costs&quot; and &quot;Store meter readings&quot; are preselected.</li><li><strong>&quot;Start values&quot;:</strong> leave &quot;Count from now&quot; selected.</li><li><strong>&quot;Name&quot;:</strong> enter a name and click &quot;⚡ Activate&quot;.</li></ol><p><img src="'+n+'" alt="The &quot;Add source&quot; wizard, &quot;Datapoint&quot; step with matching datapoints"></p><p>The wizard then waits for the first value. If that takes a while, say for PV at night, you can close it. The source keeps running. Its values are under <code>sourceanalytix.0.&lt;device&gt;</code>, where <code>&lt;device&gt;</code> is the &quot;Technical ID&quot; derived from the name.</p><p>You change all other settings later in the source&#39;s detail view under &quot;Settings&quot; and confirm with &quot;⚡ Apply&quot;. If a change deletes data, for example switching off &quot;Consumption&quot; or &quot;Costs&quot;, the page asks first.</p><h3 id="what-about-the-datapoint-on-the-objects-tab" tabindex="-1">What about the datapoint on the &quot;Objects&quot; tab? <a class="header-anchor" href="#what-about-the-datapoint-on-the-objects-tab" aria-label="Permalink to &quot;What about the datapoint on the &quot;Objects&quot; tab?&quot;">​</a></h3><p>There is only a switch there, so you can see in the object tree which datapoints SourceAnalytix uses. If you switch it on, the price definition is still missing, and the source shows up on the &quot;Problems&quot; tab. Switching it off removes the source&#39;s settings, including the start values. To pause a source, use &quot;Deactivate&quot; in the instance settings.</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#datapoint-settings-costs-consumption-meter">What do the datapoint settings do?</a> · <a href="./../fehlerbehebung/log-meldungen#datapoint-enabled-but-no-folders">Datapoint enabled, but no folders appear</a></p><p><a id="values-consumption-today-yesterday"></a></p><h2 id="where-do-i-find-my-values-daily-consumption-today-yesterday" tabindex="-1">Where do I find my values (daily consumption today/yesterday)? <a class="header-anchor" href="#where-do-i-find-my-values-daily-consumption-today-yesterday" aria-label="Permalink to &quot;Where do I find my values (daily consumption today/yesterday)?&quot;">​</a></h2><p>On the &quot;Overview&quot; tab: every card shows &quot;Today&quot;, &quot;Month&quot; and &quot;Year&quot;, and the detail view under &quot;Values&quot; also shows &quot;Yesterday&quot;, &quot;Last month&quot; and more. As states they are under <code>sourceanalytix.0.&lt;device&gt;.currentYear</code>.</p><table tabindex="0"><thead><tr><th>State under <code>sourceanalytix.0.&lt;device&gt;</code></th><th>Content</th></tr></thead><tbody><tr><td><code>cumulativeReading</code></td><td>total</td></tr><tr><td><code>currentYear.consumed.01_currentDay</code> to <code>05_currentYear</code></td><td>today, this week, month, quarter, year</td></tr><tr><td><code>currentYear.consumed.01_previousDay</code> to <code>05_previousYear</code></td><td>yesterday, last week, last month, last quarter, last year</td></tr><tr><td><code>currentYear.costs.…</code></td><td>costs with the same names</td></tr></tbody></table><p>For feed-in, the folders are called <code>delivered</code> and <code>earnings</code>. The running values appear with the source&#39;s first value; &quot;yesterday&quot; and the other previous periods only after the first period rollover. SourceAnalytix only calculates when the source sends a new value.</p><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Where do I find yesterday, last week, last month?</a> · <a href="./../hintergrund/perioden-und-zeit#values-updated-live-midnight">Values live or only at midnight?</a></p>',40)])])}const q=e(i,[["render",s]]);export{y as __pageData,q as default};
